param([ValidateSet(1,2)][int]$Revision=1)
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue'
. "$PSScriptRoot/incident-common.ps1"
$process=$null;$started=$false;$headers=$null;$stage='START';$localName='meta-ads-incident-machine-20261019'
try{
 $plan=Read-IncidentPrivate "runtime-merge-v$Revision";$old=Read-IncidentPrivate 'compromised-baseline';$fresh=Read-IncidentPrivate 'fresh-core-v2'
 $snapshot=Get-IncidentSnapshot;Assert-IncidentContained $snapshot
 if($snapshot.runtime_role.login -cne $true -or (Get-NetTCPConnection -LocalPort 48080 -State Listen -ErrorAction SilentlyContinue)){throw 'LOCAL_PRECONDITION'}
 $existing=& docker container ls --all --filter "name=^/$localName`$" --format '{{.Names}}' 2>$null;if($LASTEXITCODE -ne 0 -or $existing){throw 'LOCAL_CONTAINER_EXISTS'}
 $environment=@{};foreach($name in $plan.after.Keys){$environment[$name]=$plan.after[$name]};$environment.DAILY_SYNC_FEATURE_ENABLED='true';$environment.DAILY_SYNC_SCHEDULE_ENABLED='false'
 foreach($name in @('PHASE08_GOOGLE_ADC_JSON_B64','PHASE08_META_RECORD_B64','DAILY_SYNC_META_VAULT_KEY','DAILY_SYNC_CAFE24_CLIENT_SECRET','DAILY_SYNC_CREDENTIAL_KEY_V1')){if($environment.ContainsKey($name)){throw 'PROVIDER_CREDENTIAL_PRESENT'}}
 $program="let x='';process.stdin.on('data',c=>x+=c);process.stdin.on('end',async()=>{let p,s='PREPARE';try{const e={...process.env,...JSON.parse(x)};x='';const{preparePhase08Runtime}=await import('/srv/app/deploy/cloud/phase08-launch.mjs');const{launchBundle}=await import('/srv/app/deploy/launch-bundle.mjs');p=await preparePhase08Runtime(e);s='LAUNCH';const b=launchBundle({env:p.env,logError:v=>console.error('INCIDENT_BUNDLE_SAFE_FAILURE '+JSON.stringify({event:v.event,child:v.child,code:typeof v.code==='number'||/^[A-Z_0-9]{1,64}$/.test(v.code??'')?v.code:null}))});s='RUNNING';await b.completion;}catch{console.error('INCIDENT_CHILD_SAFE_STAGE_'+s);process.exitCode=1;}finally{if(p)await p.cleanup();}});"
 $psi=[Diagnostics.ProcessStartInfo]::new('docker');$psi.UseShellExecute=$false;$psi.CreateNoWindow=$true;$psi.RedirectStandardInput=$true;$psi.RedirectStandardOutput=$true;$psi.RedirectStandardError=$true
 foreach($arg in @('run','--rm','--name',$localName,'--interactive','--memory','1000000000','--cpus','1','--read-only','--tmpfs','/tmp:rw,noexec,nosuid,size=64m','--publish','127.0.0.1:48080:8000',"meta-ads-incident:20261019-v$Revision",'node','-e',$program)){$psi.ArgumentList.Add($arg)}
 $process=[Diagnostics.Process]::new();$process.StartInfo=$psi;$null=$process.Start();$started=$true;$out=$process.StandardOutput.ReadToEndAsync();$err=$process.StandardError.ReadToEndAsync();$wire=$environment|ConvertTo-Json -Compress -Depth 35;$process.StandardInput.Write($wire);$process.StandardInput.Close();$wire=$null;$environment=$null
 $stage='LOCAL_READY';$headers=@{'x-internal-probe-token'=$fresh.changes.INTERNAL_PROBE_TOKEN};$ready=$false;$deadline=[DateTimeOffset]::UtcNow.AddSeconds(50)
 while([DateTimeOffset]::UtcNow -lt $deadline){if($process.HasExited){throw 'LOCAL_PROCESS_EXITED'};try{$r=Invoke-WebRequest -Uri 'http://127.0.0.1:48080/backend-api/health/ready' -Headers $headers -TimeoutSec 3 -MaximumRedirection 0 -SkipHttpErrorCheck;if([int]$r.StatusCode -eq 200){$ready=$true;break}}catch{};Start-Sleep -Milliseconds 500}
 if(-not $ready){throw 'LOCAL_READY_TIMEOUT'};$body=$r.Content|ConvertFrom-Json -AsHashtable;if($body.releaseId -cne $plan.commit){throw 'LOCAL_RELEASE'};$headers.Clear()
 $limits=& docker inspect --format '{{.HostConfig.Memory}} {{.HostConfig.NanoCpus}}' $localName 2>$null;if($LASTEXITCODE -ne 0 -or $limits -cne '1000000000 1000000000'){throw 'LOCAL_RESOURCE_LIMIT'}
 $stage='LOCAL_OLD_NEW_MACHINE';$statuses=@();foreach($token in @($old.variables.DAILY_SYNC_MACHINE_TOKEN,$fresh.changes.DAILY_SYNC_MACHINE_TOKEN)){$headers=@{'x-daily-sync-token'=$token;'x-daily-sync-target'=$plan.after.RUNTIME_API_TARGET_ID};$r=Invoke-WebRequest -Uri 'http://127.0.0.1:48080/backend-api/internal/daily-sync/status' -Method Post -Headers $headers -Body '{}' -ContentType 'application/json' -TimeoutSec 15 -MaximumRedirection 0 -SkipHttpErrorCheck;$statuses+=@([int]$r.StatusCode);$headers.Clear()}
 if($statuses.Count -ne 2 -or $statuses[0] -ne 403 -or $statuses[1] -ne 400){throw 'LOCAL_MACHINE_BOUNDARY'}
 $after=Get-IncidentSnapshot;$preserved=0;foreach($t in $snapshot.table_digests){if($t.table -cin @('security_audit_events','security_rate_limit_buckets')){continue};$n=@($after.table_digests|Where-Object{$_.table -ceq $t.table});if($n.Count -ne 1 -or $n[0].rows -ne $t.rows -or $n[0].md5 -cne $t.md5){throw 'LOCAL_BUSINESS_PRESERVATION'};$preserved++}
 $receipt=@{kind='INCIDENT_MACHINE_SAME_IMAGE_LOCAL_PROOF';at=[DateTimeOffset]::UtcNow.ToString('o');status='PASS';oldMachineStatus=$statuses[0];newMachineStatus=$statuses[1];newTokenPassedGuardReachedInvalidDto=$true;localFeatureEnabled=$true;remoteFeatureChanged=$false;localScheduleEnabled=$false;providerCredentialCapsulesPresent=0;providerRequests=0;businessWrites=0;unchangedTableDigests=$preserved;memoryBytes=1000000000;cpuCount=1;secretsInDockerConfigEnvironment=0;releaseId=$plan.commit;sourceSha=$plan.source;remotePositiveProof=$false};Write-IncidentReceipt $receipt 'machine-local-verified-decimal-gb';$receipt|ConvertTo-Json -Depth 6
}catch{$childStage=$null;$readOnlyFailure=$false;$bundleFailure=$false;$failureEvents=@();$categories=@();if($process -and $process.HasExited){$captured=$err.GetAwaiter().GetResult()+$out.GetAwaiter().GetResult();$m=[regex]::Match($captured,'INCIDENT_CHILD_SAFE_STAGE_(PREPARE|LAUNCH|RUNNING)');if($m.Success){$childStage=$m.Groups[1].Value};$readOnlyFailure=$captured -match 'EROFS|read-only file system';$bundleFailure=$captured.Contains('INCIDENT_BUNDLE_SAFE_FAILURE');foreach($match in [regex]::Matches($captured,'INCIDENT_BUNDLE_SAFE_FAILURE (\{[^\r\n]{1,200}\})')){$failureEvents+=($match.Groups[1].Value|ConvertFrom-Json)};foreach($category in @('PrismaClientInitializationError','ENOENT','EACCES','credential','meta','Google','CAFE24','certificate','configuration','not found','required','database')){if($captured.Contains($category)){$categories+=@($category)}};$captured=$null};@{kind='INCIDENT_MACHINE_LOCAL_SAFE_REJECTION';stage=$stage;childStage=$childStage;readOnlyFailure=$readOnlyFailure;bundleFailure=$bundleFailure;events=$failureEvents;categories=$categories;rawErrorSuppressed=$true}|ConvertTo-Json -Depth 5;exit 1}
finally{
 if($headers){$headers.Clear()};if($started){$discard=& docker stop --time 10 $localName 2>&1;$discard=$null;if($process -and -not $process.HasExited){$process.WaitForExit(15000)|Out-Null};if($process){$process.Dispose()}};$old=$null;$fresh=$null;$plan=$null;$wire=$null;$environment=$null;$r=$null;$token=$null
}
